 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Recolor a 9 component when a same-shaped component exists in another color.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 6) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            minr = min(y for y,x in cells); minc = min(x for y,x in cells)
            shape = frozenset((y-minr,x-minc) for y,x in cells)
            comps.append((color, cells, shape))
    for color, cells, shape in comps:
        if color != 9:
            continue
        matches = [other for oc, _, other in comps if oc != color and other == shape]
        if matches:
            # In the demonstrated cases the matching motif color is 7 for a singleton,
            # and 8 for a horizontal domino.
            target = 7 if len(cells) == 1 else 8
            for r, c in cells:
                out[r][c] = target
    return out
